/* Embedded copies of the opening painting and its motion mask, loaded only when the page is
   opened as a file (file://), where browsers forbid WebGL from reading local images.
   Regenerate if images/dream-of-arcadia-3600.webp or images/dream-of-arcadia-mask.png change. */
window.__arcadiaEmbed = {
  img: "data:image/webp;base64,",
  mask: "data:image/png;base64,"
};
